import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Checkout } from './Checkout';

// Mock contexts - I can feel these will cause problems
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({ useCart: () => mockCart }));
vi.mock('./PaymentContext', () => ({ usePayment: () => mockPayment }));

describe('Checkout', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Widget', price: 29.99 }];
  });

  // Wait... empty cart edge case first
  describe('Edge Cases', () => {
    it('displays empty cart message when no items', () => {
      mockCart.items = [];
      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent('Your cart is empty');
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  // Happy path - but I'm watching for trouble
  describe('Complete Checkout Flow', () => {
    it('navigates through all steps to confirmation', async () => {
      mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });
      const onComplete = vi.fn();

      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Main St');
      await user.type(screen.getByLabelText(/city/i), 'Springfield');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step - this is where things usually go wrong
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'John Doe');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/\$29\.99/)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent('ORD-12345');
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // The tests are going to fail here... I can feel it
  describe('Shipping Validation', () => {
    it('shows error for invalid ZIP code', async () => {
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  describe('Payment Error Recovery', () => {
    it('displays payment failure and allows retry', async () => {
      mockPayment.processPayment.mockRejectedValueOnce(new Error('Card declined'));

      // ... navigate to review step
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent('Card declined');
      });

      // Back button still enabled for recovery
      expect(screen.getByRole('button', { name: /back/i })).not.toBeDisabled();
    });
  });

  describe('Accessibility', () => {
    it('has proper ARIA labels on checkout progress', () => {
      render(<Checkout />);
      expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
    });
  });
});
